import heapq


class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def mergeKLists(lists):
    heap = []
    for i, vals in enumerate(lists):
        node = build(vals)
        if node:
            heap.append((node.val, i, node))
    heapq.heapify(heap)
    dummy = ListNode()
    tail = dummy
    while heap:
        _, i, node = heapq.heappop(heap)
        tail.next = node
        tail = node
        if node.next:
            heapq.heappush(heap, (node.next.val, i, node.next))
    out = []
    cur = dummy.next
    while cur:
        out.append(cur.val)
        cur = cur.next
    return out
